def _causal_pad(V_prog: np.ndarray, lag_length: float):
    """[v1.0.25 C2] 진행방향 '과거'로 lag_length·_LAG_PAD_NLV 만큼 확장한 격자와 pad 점수.

    반환 (V_ext, npad). npad=0 이면 확장 불가/불필요(단일점·비유한·L_V≤0·간격 0 격자).
    pad 격자는 데이터 격자에 묶지 않는다 — 커널 해상(간격 ≤ L_V/20)만 지키는 coarse 격자로
    잡아 점수 상한(_LAG_PAD_MAXPTS)이 실질 제약이 되지 않게 한다. 호출측은 확장 격자에서
    ξ_eq 를 재평가해 인과 적분한 뒤 원 격자 부분([npad:])만 절단 반환한다 — 평가창 시작점
    의존(원본 최대 100%)을 제거한다(test_gates_v1025 G-창 ≤1%).
    """
    n = V_prog.size
    if n < 2 or not np.isfinite(lag_length) or lag_length <= 0.0:
        return (V_prog, 0)
    step = float(V_prog[1] - V_prog[0])
    if step == 0.0:
        return (V_prog, 0)
    need = _LAG_PAD_NLV * lag_length
    pstep = min(abs(step), lag_length / 20.0)
    npad = int(np.ceil(need / pstep))
    if npad <= 0:
        return (V_prog, 0)
    if npad > _LAG_PAD_MAXPTS:
        npad = _LAG_PAD_MAXPTS
        pstep = need / npad
    sgn = 1.0 if step > 0 else -1.0
    pre = V_prog[0] - sgn * pstep * np.arange(npad, 0, -1)
    return (np.concatenate([pre, V_prog]), npad)

